SELECT COUNT(*) FROM chem_info WHERE deleted = 0
AND (code LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%') OR cas_no LIKE CONCAT('%', #{keyword}, '%'))
AND category = #{category} AND status = #{status}

SELECT b.*, ci.name AS chemical_name, cab.name AS cabinet_name FROM chem_batch b LEFT JOIN chem_info ci ON b.chemical_id = ci.id LEFT JOIN storage_cabinet cab ON b.cabinet_id = cab.id
b.chemical_id = #{chemicalId}
ORDER BY b.id DESC LIMIT #{size} OFFSET #{offset}
